# Write your MySQL query statement below
SELECT a1.machine_id, ROUND(AVG(a2.timestamp - a1.timestamp),3) as processing_time FROM Activity as a1 LEFT JOIN Activity as a2 ON a1.machine_id = a2.machine_id And a1.process_id = a2.process_id WHERE a2.activity_type  = 'end' and a1.activity_type = 'start' GROUP BY a1.machine_id